WITH kept_keys AS (SELECT id FROM promotions INTERSECT SELECT id FROM promotions WHERE MONTH(starts_on) IN (1, 5, 12)), reconciled AS (SELECT s.* FROM promotions s INNER JOIN kept_keys k ON s.id = k.id) SELECT CASE WHEN discount_pct >= 0.29 THEN 'HIGH' ELSE 'LOW' END AS discount_pct_tier, COUNT(*) AS num_rows, PERCENTILE_APPROX(discount_pct, ARRAY(0.25, 0.5, 0.75)) AS discount_pct_quartiles, COUNT(CASE WHEN promo_code = 'SPRING10' THEN 1 END) AS spring10_count, COUNT(*) AS num_rows_2 FROM reconciled GROUP BY discount_pct_tier;
